package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Category string `json:"category"`
	MinPrice string `json:"min_price"`
	MaxPrice string `json:"max_price"`
	SortBy   string `json:"sort_by"`
	Tags     string `json:"tags"`
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	Desc  string  `json:"description"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// buildSearchQuery constructs a dynamic search query based on filters
func buildSearchQuery(req SearchRequest) string {
	var conditions []string
	base := "SELECT id, name, price, description FROM products WHERE 1=1"

	if req.Category != "" {
		// Category uses an allowlist check
		allowed := map[string]bool{"electronics": true, "clothing": true, "food": true, "books": true}
		if allowed[strings.ToLower(req.Category)] {
			conditions = append(conditions, fmt.Sprintf(" AND category = '%s'", strings.ToLower(req.Category)))
		}
	}

	if req.MinPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price >= %s", req.MinPrice))
	}

	if req.MaxPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price <= %s", req.MaxPrice))
	}

	// Tags filter - supports comma-separated tag names for IN clause
	if req.Tags != "" {
		tagList := strings.Split(req.Tags, ",")
		quoted := make([]string, len(tagList))
		for i, t := range tagList {
			quoted[i] = fmt.Sprintf("'%s'", strings.TrimSpace(t))
		}
		conditions = append(conditions, fmt.Sprintf(" AND id IN (SELECT product_id FROM product_tags WHERE tag_name IN (%s))", strings.Join(quoted, ",")))
	}

	query := base + strings.Join(conditions, "")

	// Sort handling
	if req.SortBy != "" {
		validSorts := map[string]bool{"price": true, "name": true, "id": true}
		if validSorts[req.SortBy] {
			query += " ORDER BY " + req.SortBy
		}
	}

	query += " LIMIT 50"
	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	query := buildSearchQuery(req)
	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
